/** Render an inline SVG icon; returns '' for unknown names. */
function icon(string $name, string $class = ''): string
{
    if (!isset(APP_ICONS[$name])) {
        return '';
    }
    $cls = trim('icon ' . $class);
    return '<svg class="' . e($cls) . '" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" focusable="false">'
        . APP_ICONS[$name] . '</svg>';
}

